import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Proyeccion } from '../../proyecciones/entities/proyeccion.entity';
import { Tecnico } from '../../tecnicos/entities/tecnico.entity';

@Injectable()
export class AsignarTecnicoRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Proyeccion) private readonly proyecciones: Repository<Proyeccion>,
    @InjectRepository(Tecnico) private readonly tecnicos: Repository<Tecnico>
  ) {}

  buscarProyeccionRepository(proyeccionId: number) {
    return this.proyecciones.findOneBy({ id: proyeccionId });
  }

  buscarTecnicoRepository(tecnicoId: number) {
    return this.tecnicos.findOneBy({ id: tecnicoId });
  }

  async asignarTecnicoRepository(proyeccionId: number, tecnicoId: number, rol: string) {
    const asignacion = { proyeccionId, tecnicoId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarTecnicoRepository } from './repository';

@Injectable()
export class AsignarTecnicoService {
  constructor(private readonly repository: AsignarTecnicoRepository) {}

  async asignarTecnicoService(proyeccionId: number, tecnicoId: number, rol: string) {
    const proyeccion = await this.repository.buscarProyeccionRepository(proyeccionId);
    const tecnico = await this.repository.buscarTecnicoRepository(tecnicoId);
    if (!proyeccion || !tecnico) {
      throw new NotFoundException('No existe la proyeccion o el tecnico');
    }

    try {
      return await this.repository.asignarTecnicoRepository(proyeccionId, tecnicoId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El tecnico ya está asignado a esa proyeccion');
      }
      throw error;
    }
  }
}

